package com.example.rokidkeyboardbridge;
import android.content.*;import org.json.*;import java.io.*;
public final class AnswerOutboxChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("answer outbox "+n);}public static int run(Context c)throws Exception{n=0;AnswerOutbox.file(c).delete();String key="4".repeat(64);AnswerOutbox.pair(c,"synthetic question","synthetic answer",key,"Gemini");ok(AnswerOutbox.read(c).length()==2);ok(AnswerOutbox.summary(c).getInt("pendingAnswers")==1);ok(!new String(AnswerOutbox.file(c).readFully(),"UTF-8").contains("synthetic answer"));String id=AnswerOutbox.read(c).getJSONObject(1).getString("id");AnswerOutbox.pair(c,"synthetic question","synthetic answer",key,"Gemini");ok(AnswerOutbox.read(c).length()==2);AnswerOutbox.acknowledge(c,"f".repeat(64));ok(AnswerOutbox.read(c).length()==2);AnswerOutbox.acknowledge(c,id);ok(AnswerOutbox.read(c).length()==1);ok(AnswerOutbox.summary(c).getInt("pendingAnswers")==0);AnswerOutbox.acknowledge(c,id);ok(AnswerOutbox.read(c).length()==1);boolean failed=false;try{AnswerOutbox.pair(c,"new","x".repeat(64001),"","Gemini");}catch(IOException e){failed=true;}ok(failed);ok(AnswerOutbox.read(c).length()==1);String legacy=AnswerOutbox.enqueue(c,"Gemini","past","",123,true);ok(legacy.equals(AnswerOutbox.enqueue(c,"Gemini","past","",123,true)));ok(AnswerOutbox.read(c).length()==2);ok(AnswerOutbox.eligible("Assistant"));AnswerOutbox.file(c).delete();return n;}
}
